import { useLocation } from 'react-router-dom';
import { format } from "date-fns";
import { CorpLogo } from "../../asset/image";
import { FaWhatsapp, FaInstagram, FaEnvelope, FaLinkedin, FaFacebook } from "react-icons/fa";

const Footer = (props: { [key: string]: any }) => {

    const location = useLocation()
    const { linkShowNavbar } = props;
    const socials = [
        { icon: <FaWhatsapp />, href: "https://wa.me/6285701811781", color: "bg-green-500" },
        { icon: <FaInstagram />, href: "https://instagram.com/naufalw__", color: "bg-pink-500" },
        { icon: <FaFacebook />, href: "https://instagram.com/naufalw__", color: "bg-cyan-600" },
        { icon: <FaEnvelope />, href: "mailto:naufal.wijaya9a@gmail.com", color: "bg-slate-500" },
        { icon: <FaLinkedin />, href: "https://www.linkedin.com/in/naufal-wijaya-a788b21b8", color: "bg-sky-600" },
    ];
    return (
        <div style={{ display: (linkShowNavbar.includes(location.pathname)) ? undefined : "none" }} className="w-full mx-auto bg-blue-950 mt-32">
            <div className="w-11/12 md:w-10/12 mx-auto py-12 flex flex-col md:flex-row items-center md:items-start justify-between gap-10">

                {/* Logo + tagline */}
                <div className="flex flex-col items-center md:items-start text-center md:text-left gap-3">
                    <img
                        src={CorpLogo}
                        alt="REGARDE Logo"
                        className="w-20 drop-shadow-md bg-white rounded-md p-2"
                    />
                    <h4 className="font-bold text-xl tracking-wide text-white">REGARDE</h4>
                    <p className="text-sm text-white max-w-sm">
                        Kami telah tersertifikasi ISO 9001, ISO 14001, dan ISO 45001 sebagai bentuk komitmen terhadap kualitas, keselamatan, dan keberlanjutan.
                    </p>
                </div>

                {/* Quick Links */}
                <div className="flex flex-col items-center md:items-start gap-3">
                    <h5 className="font-semibold text-lg text-white">Quick Links</h5>
                    <a href="certifications" className="text-white hover:text-sky-300">Certifications</a>
                    <a href="virtual-office" className="text-white hover:text-sky-300">Virtual Office</a>
                    <a href="intellectual-property" className="text-white hover:text-sky-300">Intellectual Property</a>
                    <a href="law-firm" className="text-white hover:text-sky-300">Law Firm</a>
                    <a href="advertising" className="text-white hover:text-sky-300">Advertising</a>
                </div>

                {/* Social Media */}
                <div className="flex flex-col items-center md:items-start gap-3">
                    <h5 className="font-semibold text-lg text-white">Connect</h5>
                    <div className="flex gap-4 mt-2">
                        {socials.map((s, i) => (
                            <a
                                key={i}
                                href={s.href}
                                target="_blank"
                                rel="noopener noreferrer"
                                className={`${s.color} text-white text-lg w-10 h-10 flex items-center justify-center rounded-full shadow-md hover:scale-110 transition-transform duration-300`}
                            >
                                {s.icon}
                            </a>
                        ))}
                    </div>
                </div>
            </div>

            {/* Bottom copyright */}
            <div className="border-t border-sky-700 py-4">
                <p className="text-center text-sm text-white">
                    © {format(new Date(), "yyyy")} REGARDE. All rights reserved.
                </p>
            </div>
        </div>
    )
}

export default Footer
